type RESPONSE_DATA = {
  greeting: string;
};

const getJson = async <T>(endpoint: string): Promise<T> => {
  // Проверяем, в каком режиме мы работаем
  const path =
    process.env.NODE_ENV === 'development'
      ? `http://localhost:3001/api/${endpoint}` // Режим разработки
      : `https://raw.githubusercontent.com/pollinsss/gh-pages-demo/gh-pages/static/db/${endpoint}.json`; // Режим продакшена

  const response = await fetch(path);
  return await response.json();
};

type API = {
  get: {
    data: () => Promise<RESPONSE_DATA>;
  };
};

const api: API = {
  get: {
    data: () => getJson<RESPONSE_DATA>('data'),
  },
};

export type { RESPONSE_DATA };
export default api;